// Normalize text kwa search
function normalize(text) {
  return String(text).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

export function searchAll(query, limit = 20) {
  if (!query || query.length < 2) return [];
  const q = normalize(query);
  const results = [];

  for (const item of SEARCH_INDEX) {
    const titleNorm = normalize(item.title);
    const keywordsNorm = normalize(item.keywords || "");
    let score = 0;

    if (titleNorm.includes(q)) score += 10;
    if (keywordsNorm.includes(q)) score += 5;
    if (titleNorm.startsWith(q)) score += 5;

    if (score > 0) {
      results.push({ ...item, score });
    }
  }

  return results.sort((a, b) => b.score - a.score).slice(0, limit);
}

export function getCategories() {
  return ["Somo", "Kampuni", "Soko", "Somo la Mwezi"];
}
